import{d as f,C as l,o as q,c as k,j as e,a as i,E as t,a3 as P}from"./chunks/framework.Q4yG9rk_.js";const v=JSON.parse('{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","frontmatter":{"title":"千字文 · 全篇","description":"《千字文》全篇一千字，按内容分八节，逐节给原文、引读与字词。","category":"guide","aliases":["千字文","千字文全篇"],"source":["《千字文》（通行本）"]},"headers":[],"relativePath":"lizhimingde/qianziwen/chapter-01.md","filePath":"lizhimingde/qianziwen/chapter-01.md","lastUpdated":1790334155000}'),S={name:"lizhimingde/qianziwen/chapter-01.md"},C=f({...S,setup(T){const o=[{id:"jie1_s1",label:"天地玄黄，宇宙洪荒",showLabel:!0,sentences:[[{text:"天地",glossary:"tiandi"},"玄黄，宇宙",{text:"洪荒",glossary:"honghuang"},"。"]],note:["天色深玄，地色黄厚；宇宙初开，洪蒙荒远。两句定下全篇格局：先立天地，再立时空。","【出处】语本《易·坤·文言》：「夫玄黄者，天地之杂也，天玄而地黄。」「宇」指上下四方，「宙」指古往今来——「宇宙」二字合起来，就是时间与空间。"]},{id:"jie1_s2",label:"日月盈昃，辰宿列张",showLabel:!0,sentences:[["日月盈",{text:"昃",glossary:"ze"},"，辰宿列张。"]],note:["太阳到了中天就要偏西（昃），月亮圆了就要变缺（盈）；星辰罗列，布满天空。","【出处】《易·丰》：「日中则昃，月盈则食。」讲的正是同一个道理：到极处就要转。「辰」泛指星辰，「宿」（xiù）为星宿，后世二十八宿之说即由此而来。"]},{id:"jie1_s3",label:"寒来暑往，秋收冬藏",showLabel:!0,sentences:[["寒来暑往，秋收冬藏。"]],note:["冷来了、热去了，四季轮转；秋天收进仓，冬天藏起来。这是古人描述一年运转最朴素的一句，也是农事与人事共同的节拍。","【参看】《尚书·尧典》「历象日月星辰，敬授民时」——观天象以定农时，是上古治道的第一件事。"]},{id:"jie1_s4",label:"闰余成岁，律吕调阳",showLabel:!0,sentences:[[{text:"闰余",glossary:"runyu"},"成岁，",{text:"律吕",glossary:"lvlv"},"调阳。"]],note:["把每年多出来的零头日子攒成闰月，一年才不至于和寒暑错位；六律六吕与十二月相应，用来校正节气中的阴阳之气。上句管「年」，下句管「气」。","【出处】「闰余」见《尚书·尧典》「以闰月定四时成岁」；「律吕」为古乐十二音，六律为阳、六吕为阴。古人以律管候气，观葭灰飞动来验节气——这是中国最早的「历律相通」之说。"]},{id:"jie1_s5",label:"云腾致雨，露结为霜",showLabel:!0,sentences:[["云腾致雨，露结为霜。"]],note:["云气上腾，落下来就是雨；夜里水汽凝结，冷到极处就成了霜。两句写水的升降往复。","【出处】《易·系辞》有「云行雨施，品物流形」；《礼记·月令》记季秋之月「霜始降」。"]},{id:"jie1_s6",label:"金生丽水，玉出昆冈",showLabel:!0,sentences:[["金生",{text:"丽水",glossary:"lishui"},"，玉出",{text:"昆冈",glossary:"kungang"},"。"]],note:["黄金出于丽水，美玉产自昆仑山。由天象寒暑转到地上最贵重之物，是全节的转折处。","【出处】「丽水」一说即金沙江，其地出金；「昆冈」即昆仑山，古以产玉著称。《尚书·胤征》有「火炎昆冈，玉石俱焚」，可见昆仑产玉之说上古已有。"]},{id:"jie1_s7",label:"剑号巨阙，珠称夜光",showLabel:!0,sentences:[["剑号",{text:"巨阙",glossary:"juque"},"，珠称",{text:"夜光",glossary:"yeguang"},"。"]],note:["宝剑里最有名的是「巨阙」，宝珠里最珍贵的是「夜光」。承上句金玉，由「物产」说到「名品」。","【典故】「巨阙」相传为春秋时越王勾践所铸，《越绝书》记欧冶子铸剑，巨阙为其一；「夜光」指夜明珠，一说即隋侯之珠（见《淮南子·览冥》高诱注）。"]},{id:"jie1_s8",label:"果珍李柰，菜重芥姜",showLabel:!0,sentences:[["果珍李",{text:"柰",glossary:"nai"},"，菜重芥姜。"]],note:["水果中李子和柰最受珍视，菜蔬里芥菜和生姜最被看重。前面讲难得之物，这里落到日常饮食，开始往人间的日子上走。","【出处】「柰」即古时的绵苹果，《礼记·内则》有「枣栗饴蜜以甘之」，可见古人论食重味；芥、姜取其辛，是日常调味的根本。"]},{id:"jie1_s9",label:"海咸河淡，鳞潜羽翔",showLabel:!0,sentences:[["海咸河淡，",{text:"鳞潜羽翔",glossary:"linqian"},"。"]],note:["海水是咸的，河水是淡的；鱼在水里潜游，鸟在天上飞翔。以水陆众生收束全节，也把「天地」这一层写完。","【参看】《管子·水地》以水为「万物之本原」。此句上承天象、下接地物，一层自然地至此收住。"]}],r=[{id:"tiandi",term:"天地",pinyin:"tiān dì",meaning:"天与地。天色玄、地色黄，语本《易·坤·文言》「夫玄黄者，天地之杂也，天玄而地黄」。"},{id:"honghuang",term:"洪荒",pinyin:"hóng huāng",meaning:"广大荒远、浑沌未分的样子。宇指上下四方，宙指古往今来，「宇宙」合起来就是时间与空间。"},{id:"ze",term:"昃",pinyin:"zè",meaning:"日西斜。日月盈昃，说的是月由圆到缺、日由中天到西斜，都是运行。《易·丰》「日中则昃，月盈则食」讲的是同一个道理。"},{id:"runyu",term:"闰余",pinyin:"rùn yú",meaning:"历法术语。阴历一年约三百五十四日，与太阳年差约十一日，三年一闰、五年再闰，才不至于寒暑错位。"},{id:"lvlv",term:"律吕",pinyin:"lǜ lǚ",meaning:"古乐十二音：六律为阳、六吕为阴。古人以十二律与十二月相应，用律管候气来调正节气。"},{id:"lishui",term:"丽水",pinyin:"lì shuǐ",meaning:"古称金沙江为丽水，一说其地出金。「金生丽水」即金沙出于丽水。"},{id:"kungang",term:"昆冈",pinyin:"kūn gāng",meaning:"昆仑山，古以为产玉之地。《尚书·胤征》有「火炎昆冈，玉石俱焚」之语。"},{id:"juque",term:"巨阙",pinyin:"jù què",meaning:"春秋时越王勾践所铸宝剑之名，与湛卢、纯钩等并称。"},{id:"yeguang",term:"夜光",pinyin:"yè guāng",meaning:"夜明珠。一说即隋侯之珠，夜里能发光。"},{id:"nai",term:"柰",pinyin:"nài",meaning:"柰树之果，形似苹果而小。果珍李柰，指果中珍品是李与柰。"},{id:"linqian",term:"鳞潜羽翔",pinyin:"lín qián yǔ xiáng",meaning:"鱼在水中潜、鸟在空中翔——由海河写到水陆众生，收束这一节的自然之景。"}],g=[{id:"jie2_s1",label:"龙师火帝，鸟官人皇",showLabel:!0,sentences:[[{text:"龙师",glossary:"longshi"},"火帝，",{text:"鸟官",glossary:"niaoguan"},"人皇。"]],note:["伏羲以龙名官（龙师），神农号火帝，少昊以鸟名官（鸟官），再加人皇，合起来是传说中最早的一批君主。","【典故】《左传·昭公十七年》记郯子说少昊「纪于鸟，为鸟师而鸟名」，可见以鸟名官之说甚古；「火帝」指神农氏，因教民熟食、又号炎帝；「人皇」为三皇之一，与天皇、地皇并举。据传以龙名官者为太昊伏羲氏。"]},{id:"jie2_s2",label:"始制文字，乃服衣裳",showLabel:!0,sentences:[["始制文字，乃服衣裳。"]],note:["开始造出文字，进而穿上衣裳——文明的两大标志：一个通信息，一个分尊卑。","【典故】相传仓颉造字，见《说文解字·叙》「黄帝之史仓颉……初造书契」；衣裳之制则归功于嫘祖，《史记·五帝本纪》记黄帝「娶于西陵之女，是为嫘祖」。"]},{id:"jie2_s3",label:"推位让国，有虞陶唐",showLabel:!0,sentences:[["推位让国，有虞陶唐。"]],note:["把帝位推让出去——有虞氏（舜）与陶唐氏（尧）互相禅让。这是儒家心中最理想的一次权力交接。","【典故】尧让舜、舜让禹，见《尚书·尧典》与《孟子·万章上》。「陶唐」是尧的号，「有虞」是舜的号，故合称「唐虞」。"]},{id:"jie2_s4",label:"吊民伐罪，周发殷汤",showLabel:!0,sentences:[["吊民伐罪，周发殷汤。"]],note:["抚慰百姓、讨伐暴君的是周武王（名发）与商汤。与上句对照：一个「让」，一个「伐」——治世的两面。","【典故】商汤伐夏桀、周武王伐商纣，后世合称「汤武革命」。《孟子·梁惠王下》记孟子语：「闻诛一夫纣矣，未闻弑君也。」——暴君已失其为君之实，故伐之不为弑。"]},{id:"jie2_s5",label:"坐朝问道，垂拱平章",showLabel:!0,sentences:[["坐朝问道，",{text:"垂拱",glossary:"chuigong"},{text:"平章",glossary:"pingzhang"},"。"]],note:["端坐朝堂，询问治国之道；垂衣拱手，天下便治理得清晰分明。","【典故】「平章」出《尚书·尧典》「九族既睦，平章百姓」；「垂拱」出《尚书·武成》「垂拱而天下治」，后世专用来形容君主不必亲劳而天下自安。"]},{id:"jie2_s6",label:"爱育黎首，臣伏戎羌",showLabel:!0,sentences:[["爱育",{text:"黎首",glossary:"lishou"},"，臣伏",{text:"戎羌",glossary:"rongqiang"},"。"]],note:["爱护养育黎民百姓，使西部的戎、羌也俯首归顺。讲的是德政向外辐射：先安内，再服远。","【典故】「黎首」即黎民，指黑发的百姓；戎、羌是西方部族的泛称，见《尚书·禹贡》所记「西戎」。"]},{id:"jie2_s7",label:"遐迩一体，率宾归王",showLabel:!0,sentences:[[{text:"遐迩",glossary:"xiaer"},"一体，率宾归王。"]],note:["远近之地合为一体，万方都来归顺王化。","【典故】「率宾」语本《诗·小雅·北山》「率土之滨，莫非王臣」；「归王」则是周代「普天之下，莫非王土」这一天下观的浓缩。"]},{id:"jie2_s8",label:"鸣凤在竹，白驹食场",showLabel:!0,sentences:[["鸣凤在竹，白驹食场。"]],note:["凤凰在竹林里鸣叫，白马在场上吃草——都是太平祥瑞之象。","【典故】凤凰鸣于岐山，见《国语·周语上》；「白驹食场」出《诗·小雅·白驹》「皎皎白驹，食我场苗」，本指贤者来归，后人读作太平之世贤才得所。"]},{id:"jie2_s9",label:"化被草木，赖及万方",showLabel:!0,sentences:[["化被草木，赖及万方。"]],note:["王者的教化遍及草木，恩泽惠及天下万方。这一句把全节的「德化」推到顶。","【典故】「化被草木」上承《尚书·禹贡》「东渐于海，西被于流沙」的「被」字；《礼记·中庸》「致中和，天地位焉，万物育焉」，则是「德至草木」这一观念最完整的表述。"]}],d=[{id:"longshi",term:"龙师",pinyin:"lóng shī",meaning:"传说伏羲氏以龙名官，故称龙师，是上古以图腾纪官的标志。"},{id:"niaoguan",term:"鸟官",pinyin:"niǎo guān",meaning:"传说少昊氏以鸟名官，故称鸟官，与「龙师」对举。"},{id:"chuigong",term:"垂拱",pinyin:"chuí gǒng",meaning:"垂衣拱手。形容君主不必亲自操劳，天下自安。《尚书·武成》「垂拱而天下治」。"},{id:"pingzhang",term:"平章",pinyin:"píng zhāng",meaning:"辨别彰明。语本《尚书·尧典》「平章百姓」，指辨明政事得失。"},{id:"lishou",term:"黎首",pinyin:"lí shǒu",meaning:"黎民百姓。黎是众多，首指人民（黑发之人）。"},{id:"rongqiang",term:"戎羌",pinyin:"róng qiāng",meaning:"西戎与羌，泛指西部边地的部族。"},{id:"xiaer",term:"遐迩",pinyin:"xiá ěr",meaning:"远近。遐迩一体，指远近之地合为一体。"}],m=[{id:"jie3_s1",label:"盖此身发，四大五常",showLabel:!0,sentences:[["盖此身发，",{text:"四大",glossary:"sida"},"五常。"]],note:["人的这副身体由「四大」构成，而人生在世要靠「五常」立身——一句里把身与德两样根基一起立住。","【典故】「四大」是佛教用语，指地、水、火、风四种元素（见《圆觉经》等），此处借以说身体；「五常」为仁义礼智信，是汉儒归纳的常行之德（董仲舒《举贤良对策》始以「五常」配五行）。"]},{id:"jie3_s2",label:"恭惟鞠养，岂敢毁伤",showLabel:!0,sentences:[["恭惟",{text:"鞠养",glossary:"juyang"},"，岂敢毁伤。"]],note:["恭敬地念及父母养育之劳，哪里敢损毁自己的身体。「恭惟」是敬词，此句承上句的「身」而来。","【典故】本《孝经·开宗明义》：「身体发肤，受之父母，不敢毁伤，孝之始也。」——孝的第一步，竟是不伤自己的身体。"]},{id:"jie3_s3",label:"女慕贞洁，男效才良",showLabel:!0,sentences:[["女慕贞洁，男效才良。"]],note:["女子仰慕贞洁之德，男子效法才德兼备之人。男女各举一端，是古代蒙书的常见句式。","【典故】「贞」字见《易·恒》「妇人贞吉」；「才良」谓才与德兼备，《尚书·冏命》有「惟予一人无良」，可见「良」早为称德之词。"]},{id:"jie3_s4",label:"知过必改，得能莫忘",showLabel:!0,sentences:[["知过必改，得能莫忘。"]],note:["知道有过错一定要改，学到了本领不要忘记。与下两句合成一组，讲的都是「向内收」。","【典故】本《左传·宣公二年》：「人谁无过？过而能改，善莫大焉。」《论语·学而》亦云「过则勿惮改」。"]},{id:"jie3_s5",label:"罔谈彼短，靡恃己长",showLabel:!0,sentences:[[{text:"罔",glossary:"wang"},"谈彼短，",{text:"靡",glossary:"mi"},"恃己长。"]],note:["不要议论别人的短处，不要倚仗自己的长处。「罔」「靡」都是「不要」。","【典故】此意是汉魏以下家训常语，可参崔瑗《座右铭》「无道人之短，无说己之长」。"]},{id:"jie3_s6",label:"信使可覆，器欲难量",showLabel:!0,sentences:[["信使可",{text:"覆",glossary:"fu"},"，器欲难量。"]],note:["说出口的话要经得起反复核对，器量要大得让人难以测量。一句说「信」，一句说「量」。","【典故】「覆」是核验，《论语·学而》有「信近于义，言可复也」；「器欲难量」谓胸襟深广，语意近《世说新语》以「汪汪如万顷之陂」状人之度。"]},{id:"jie3_s7",label:"墨悲丝染，诗赞羔羊",showLabel:!0,sentences:[[{text:"墨悲丝染",glossary:"sisu"},"，",{text:"诗赞羔羊",glossary:"gaoyang"},"。"]],note:["墨子见白丝被染而悲叹，《诗经》赞美羔羊的纯白——两句都在说「保持本色」。","【典故】《墨子·所染》：墨子见染丝者而叹「染于苍则苍，染于黄则黄，所入者变，其色亦变」，故染不可不慎；「诗赞羔羊」出《诗·召南·羔羊》，毛传以为美其「俭以自守」，因羔裘洁白而群居有序。"]},{id:"jie3_s8",label:"景行维贤，克念作圣",showLabel:!0,sentences:[[{text:"景行",glossary:"jingxing"},"维贤，",{text:"克念作圣",glossary:"kenian"},"。"]],note:["效法光明的大道才能成为贤者，能克制住自己的念头便可成圣。","【典故】「景行」出《诗·小雅·车舝》「高山仰止，景行行止」；「克念作圣」出《尚书·多方》「惟圣罔念作狂，惟狂克念作圣」——圣与狂之间，只在一念收与不收。"]},{id:"jie3_s9",label:"德建名立，形端表正",showLabel:!0,sentences:[["德建名立，",{text:"形端表正",glossary:"biaozheng"},"。"]],note:["品德立起来了，名声自然跟着立；仪形端正了，仪表自然就正。这是「本立而末自随」的意思。","【典故】「表」指测日影的标杆，表正则影正——后世「身正不怕影斜」即由此而来。"]},{id:"jie3_s10",label:"空谷传声，虚堂习听",showLabel:!0,sentences:[["空谷传声，虚堂习听。"]],note:["空谷里声音传得远，空堂中回声听得清——比喻德行的影响深远而清楚。","【典故】语意本《易·系辞》「君子居其室，出其言善，则千里之外应之」；「习听」谓声音反复回响，见《礼记·乐记》「声声相应」。"]},{id:"jie3_s11",label:"祸因恶积，福缘善庆",showLabel:!0,sentences:[["祸因恶积，福缘善庆。"]],note:["祸患是因为恶行累积而来，福分是因为善行积到了可庆的地步。","【典故】本《易·坤·文言》：「积善之家，必有余庆；积不善之家，必有余殃。」「庆」即余庆、福泽。"]},{id:"jie3_s12",label:"尺璧非宝，寸阴是竞",showLabel:!0,sentences:[[{text:"尺璧",glossary:"chibi"},"非宝，",{text:"寸阴",glossary:"cunyin"},"是竞。"]],note:["一尺大的美玉算不上宝，一寸光阴才值得去争。「竞」是争先——不是爱惜，是抢着用。","【典故】「寸阴」出《淮南子·原道训》：「圣人不贵尺之璧而重寸之阴，时难得而易失也。」"]}],h=[{id:"sida",term:"四大",pinyin:"sì dà",meaning:"佛教用以说明身体的四种元素：地、水、火、风。此处与「五常」（仁义礼智信）并举——一说身、一说德。"},{id:"juyang",term:"鞠养",pinyin:"jū yǎng",meaning:"养育。恭惟鞠养，是恭敬地念及父母养育之劳。"},{id:"wang",term:"罔",pinyin:"wǎng",meaning:"不要。罔谈彼短，即不要议论别人的短处。"},{id:"mi",term:"靡",pinyin:"mǐ",meaning:"不要。靡恃己长，即不要倚仗自己的长处。"},{id:"fu",term:"覆",pinyin:"fù",meaning:"核对、验察。信使可覆，指说出口的话要经得起反复核对。"},{id:"jingxing",term:"景行",pinyin:"jǐng xíng",meaning:"大道、光明的德行。语本《诗经·小雅·车舝》「高山仰止，景行行止」。"},{id:"chibi",term:"尺璧",pinyin:"chǐ bì",meaning:"直径一尺的美玉，喻贵重之物。尺璧非宝、寸阴是竞——美玉不算宝，光阴才要争。"},{id:"sisu",term:"墨悲丝染",pinyin:"mò bēi sī rǎn",meaning:"《墨子·所染》载墨子见染丝而叹：丝「染于苍则苍，染于黄则黄」。喻人易受环境熏染，故所染不可不慎。"},{id:"gaoyang",term:"诗赞羔羊",pinyin:"shī zàn gāo yáng",meaning:"《诗·召南·羔羊》，《毛传》以为赞美在位者「俭以自守」。羔裘洁白，故以喻正直清白。"},{id:"kenian",term:"克念作圣",pinyin:"kè niàn zuò shèng",meaning:"语出《尚书·多方》「惟圣罔念作狂，惟狂克念作圣」——能克制妄念，狂者也可成圣。"},{id:"biaozheng",term:"形端表正",pinyin:"xíng duān biǎo zhèng",meaning:"「表」是测日影的标杆；形端则表正，即身正而仪表自正。后世「身正不怕影斜」由此而来。"},{id:"cunyin",term:"寸阴",pinyin:"cùn yīn",meaning:"极短的光阴。语本《淮南子·原道训》「圣人不贵尺之璧而重寸之阴，时难得而易失也」。"}],u=[{id:"jie4_s1",label:"资父事君，曰严与敬",showLabel:!0,sentences:[[{text:"资父事君",glossary:"zifushijun"},"，曰严与敬。"]],note:["侍奉父亲、服事君主，要严肃而恭敬。「资」是凭藉——以事父之道去事君，是古人「移孝作忠」的说法。","【典故】《孝经·士章》：「资于事父以事君，而敬同。」此句即从那里来。"]},{id:"jie4_s2",label:"孝当竭力，忠则尽命",showLabel:!0,sentences:[["孝当竭力，忠则尽命。"]],note:["尽孝要竭尽全力，尽忠要不惜性命。两句把「孝」与「忠」各推到它的极限。","【典故】《孝经·开宗明义》「夫孝，始于事亲，中于事君，终于立身」；《论语·学而》曾子言「事君能致其身」。"]},{id:"jie4_s3",label:"临深履薄，夙兴温凊",showLabel:!0,sentences:[[{text:"临深履薄",glossary:"linshen"},"，夙兴",{text:"温凊",glossary:"wenqing"},"。"]],note:["要像走近深渊、踩上薄冰那样谨慎；早起晚睡，冬天让父母暖、夏天让父母凉。","【典故】「临深履薄」出《诗·小雅·小旻》「战战兢兢，如临深渊，如履薄冰」；「夙兴」见《诗·卫风·氓》「夙兴夜寐」；「温凊」见《礼记·曲礼》「冬温而夏凊，昏定而晨省」。"]},{id:"jie4_s4",label:"似兰斯馨，如松之盛",showLabel:!0,sentences:[[{text:"似兰斯馨",glossary:"lanxin"},"，如松之盛。"]],note:["品德像兰花那样芬芳，节操像松树那样茂盛。以草木之性比人之德，是《千字文》常用的手法。","【参看】《孔子家语·在厄》以芝兰比善人之化；《论语·子罕》「岁寒，然后知松柏之后凋也」。"]},{id:"jie4_s5",label:"川流不息，渊澄取映",showLabel:!0,sentences:[["川流不息，",{text:"渊澄",glossary:"yuancheng"},"取映。"]],note:["像河川那样流个不停，像深潭那样清澈可以照见物影。","【参看】《论语·子罕》「逝者如斯夫，不舍昼夜」；《庄子·天道》「水静则明，须眉皆见」，皆以水喻心。"]},{id:"jie4_s6",label:"容止若思，言辞安定",showLabel:!0,sentences:[["容止若思，言辞安定。"]],note:["仪容举止沉静，像在思索；说话安详稳定，不急不躁。这两句是「敬」在外面的样子。","【出处】《礼记·玉藻》有「君子之容」的种种描写；《论语·学而》「君子不重则不威」。"]},{id:"jie4_s7",label:"笃初诚美，慎终宜令",showLabel:!0,sentences:[["笃初诚美，",{text:"慎终宜令",glossary:"duchu"},"。"]],note:["做事开头的认真诚恳固然好，能谨慎地做到最后才更值得称许。一句「有始有终」。","【典故】本《诗·大雅·荡》「靡不有初，鲜克有终」——没有不肯好好开始的，少见的是能善终。"]},{id:"jie4_s8",label:"荣业所基，籍甚无竟",showLabel:!0,sentences:[["荣业所基，",{text:"籍甚",glossary:"jishen"},"无竟。"]],note:["荣耀的事业以修身为根基；美名盛大，传之不尽。","【参看】「籍甚」见《汉书·陆贾传》「名籍甚」，「籍籍」即声名之盛。"]},{id:"jie4_s9",label:"学优登仕，摄职从政",showLabel:!0,sentences:[[{text:"学优登仕",glossary:"xueyou"},"，摄职从政。"]],note:["学业有余力就出仕，担任职务、参与政事。","【典故】本《论语·子张》子夏语：「仕而优则学，学而优则仕。」"]},{id:"jie4_s10",label:"存以甘棠，去而益咏",showLabel:!0,sentences:[["存以",{text:"甘棠",glossary:"gantang"},"，去而益咏。"]],note:["在位时像甘棠树荫那样庇护百姓，离任后百姓反而更加称颂。","【典故】召伯巡行，曾在甘棠树下听讼，他走后百姓念其德而爱其树，作《诗·召南·甘棠》「蔽芾甘棠，勿翦勿伐」。"]},{id:"jie4_s11",label:"乐殊贵贱，礼别尊卑",showLabel:!0,sentences:[["乐殊贵贱，礼别尊卑。"]],note:["乐用来区分贵贱，礼用来分别尊卑。两句讲的是「秩序」如何落地为形式。","【典故】《乐记》：「乐者为同，礼者为异。同则相亲，异则相敬。」"]},{id:"jie4_s12",label:"上和下睦，夫唱妇随",showLabel:!0,sentences:[["上和下睦，夫唱妇随。"]],note:["上下和睦相处，夫唱而妇和。前半讲位分之内的「和」，后半讲家庭之内的「顺」。","【参看】《周易·家人》「家人有严君焉，父母之谓也」。"]},{id:"jie4_s13",label:"外受傅训，入奉母仪",showLabel:!0,sentences:[["外受",{text:"傅训",glossary:"fuxun"},"，入奉母仪。"]],note:["在外接受师傅的教诲，在家奉行母亲的仪范。一外一内，把教养的两个来处说全。","【参看】《礼记·内则》详载子事父母之仪，其中母教尤为深切。"]},{id:"jie4_s14",label:"诸姑伯叔，犹子比儿",showLabel:!0,sentences:[["诸姑伯叔，",{text:"犹子",glossary:"youzi"},"比儿。"]],note:["对姑母、伯父、叔父而言，侄子就当作自己的孩子一样看待。","【典故】「犹子」出《礼记·檀弓》「兄弟之子，犹子也」。"]},{id:"jie4_s15",label:"孔怀兄弟，同气连枝",showLabel:!0,sentences:[[{text:"孔怀",glossary:"konghuai"},"兄弟，同气连枝。"]],note:["兄弟之间格外亲爱，同承一气、如树之连枝。","【典故】「孔怀」出《诗·小雅·常棣》「死丧之威，兄弟孔怀」；「同气连枝」本《吕氏春秋·精通》「一体而两分，同气而异息」。"]},{id:"jie4_s16",label:"交友投分，切磨箴规",showLabel:!0,sentences:[["交友投分，",{text:"切磨箴规",glossary:"qiemo"},"。"]],note:["交友要志趣相投；互相切磋琢磨，互相规劝告诫。","【典故】「切磨」出《诗·卫风·淇奥》「如切如磋，如琢如磨」，本指治玉，后喻朋友砥砺学问德行。"]},{id:"jie4_s17",label:"仁慈隐恻，造次弗离",showLabel:!0,sentences:[["仁慈隐恻，",{text:"造次",glossary:"zaoci"},"弗离。"]],note:["仁爱恻隐之心，在仓促紧急之时也不离身。","【典故】《孟子·公孙丑上》以「恻隐之心」为仁之端；《论语·里仁》「君子无终食之间违仁，造次必于是，颠沛必于是」。"]},{id:"jie4_s18",label:"节义廉退，颠沛匪亏",showLabel:!0,sentences:[["节义廉退，颠沛匪亏。"]],note:["节操、义气、廉洁、退让，即使颠沛流离也不亏损。「匪」同「非」，是不。","【参看】《论语·里仁》「颠沛必于是」。"]},{id:"jie4_s19",label:"性静情逸，心动神疲",showLabel:!0,sentences:[["性静情逸，心动神疲。"]],note:["本性宁静，情志就安适；心绪躁动，精神就疲惫。两句是全节的转折：由外入内。","【参看】《庄子·刻意》「纯粹而不杂，静一而不变」；《老子》「致虚极，守静笃」。"]},{id:"jie4_s20",label:"守真志满，逐物意移",showLabel:!0,sentences:[["守真志满，逐物意移。"]],note:["守住本真，志向就充实；追逐外物，心意就游移。与上两句合看，是「静」与「动」的两种结果。","【参看】《庄子·刻意》「虚无恬淡，乃合天德」。"]},{id:"jie4_s21",label:"坚持雅操，好爵自縻",showLabel:!0,sentences:[["坚持雅操，",{text:"好爵自縻",glossary:"haojue"},"。"]],note:["坚持高雅的操守，美好的爵位自然来系住你。「縻」是系住——不是去求，是它自己来。","【典故】本《易·中孚》：「我有好爵，吾与尔靡之。」"]}],b=[{id:"zifushijun",term:"资父事君",pinyin:"zī fù shì jūn",meaning:"语本《孝经·士章》「资于事父以事君，而敬同」——以事父之心事君，敬意相同。"},{id:"linshen",term:"临深履薄",pinyin:"lín shēn lǚ bó",meaning:"如临深渊、如履薄冰，形容行事极其谨慎。语本《诗·小雅·小旻》。"},{id:"lanxin",term:"似兰斯馨",pinyin:"lán xīn sōng shèng",meaning:"以兰花之馨、松树之盛比喻德行的芬芳与操守的坚贞。《家语》以芝兰喻善人之化，《论语》以松柏喻岁寒之节。"},{id:"duchu",term:"慎终宜令",pinyin:"dǔ chū shèn zhōng",meaning:"开头认真固然好，善终更可贵。语本《诗·大雅·荡》「靡不有初，鲜克有终」。"},{id:"xueyou",term:"学优登仕",pinyin:"xué yōu dēng shì",meaning:"本《论语·子张》「仕而优则学，学而优则仕」——学业有余力便出仕。"},{id:"zaoci",term:"造次",pinyin:"zào cì",meaning:"仓促、紧急之时。《论语·里仁》有「造次必于是，颠沛必于是」。"},{id:"haojue",term:"好爵自縻",pinyin:"hǎo jué zì mí",meaning:"语本《易·中孚》「我有好爵，吾与尔靡之」——守住操守，名位自然来系，不必外求。"},{id:"wenqing",term:"温凊",pinyin:"wēn qìng",meaning:"让父母冬暖夏凉。凊读 qìng，是凉爽。语本《礼记·曲礼》「冬温而夏凊，昏定而晨省」。"},{id:"yuancheng",term:"渊澄",pinyin:"yuān chéng",meaning:"深潭澄清。渊澄取映，指水静而清，可以照见物影——喻心清可鉴。"},{id:"jishen",term:"籍甚",pinyin:"jí shèn",meaning:"声名盛大、籍籍有名。籍甚无竟，指声誉传之不尽。《汉书·陆贾传》有「名籍甚」。"},{id:"gantang",term:"甘棠",pinyin:"gān táng",meaning:"周召伯巡行听政，曾在甘棠树下，后人思其德而爱其树，作《召南·甘棠》。存以甘棠、去而益咏，指在位有惠政，离去后更被怀念。"},{id:"fuxun",term:"傅训",pinyin:"fù xùn",meaning:"师傅的训导。外受傅训、入奉母仪——在外受师训，在家奉母教。"},{id:"youzi",term:"犹子",pinyin:"yóu zǐ",meaning:"侄子。语本《礼记·檀弓》「兄弟之子，犹子也」。诸姑伯叔、犹子比儿，是说对姑叔而言，侄子就如自己的孩子。"},{id:"konghuai",term:"孔怀",pinyin:"kǒng huái",meaning:"格外怀念。语本《诗经·小雅·常棣》「兄弟孔怀」，后以「孔怀」代指兄弟。"},{id:"qiemo",term:"切磨箴规",pinyin:"qiē mó zhēn guī",meaning:"切磋琢磨、规劝告诫。语本《诗经·卫风·淇奥》「如切如磋，如琢如磨」，本指治玉，后喻朋友砥砺。"}],y=[{id:"jie5_s1",label:"都邑华夏，东西二京",showLabel:!0,sentences:[["都邑华夏，东西",{text:"二京",glossary:"erjing"},"。"]],note:["都邑之中，华夏最盛的是东西两京——西京长安、东京洛阳。全节由都城的形势写起。","【典故】两京并置始于周（镐京与洛邑），汉唐因之：西汉都长安、东汉都洛阳，唐亦以长安为西京、洛阳为东京。"]},{id:"jie5_s2",label:"背邙面洛，浮渭据泾",showLabel:!0,sentences:[["背",{text:"邙",glossary:"mang"},"面洛，浮渭据泾。"]],note:["洛阳背靠北邙山、面向洛水；长安濒临渭水、凭据泾河。一山一水，各有倚仗。","【参看】古人建都讲究「形胜」，《管子·乘马》有「因天材，就地利」之说；洛阳「背邙面洛」、长安「八水绕长安」，都是这一观念的落实。"]},{id:"jie5_s3",label:"宫殿盘郁，楼观飞惊",showLabel:!0,sentences:[["宫殿盘郁，楼观飞惊。"]],note:["宫殿盘旋郁结，重重叠叠；楼阁高耸，望去像要飞去，令人心惊。","【参看】汉赋写宫室多用「飞」字，如张衡《西京赋》「反宇业业，飞檐䡾䡾」；《诗·小雅·斯干》「如跂斯翼，如矢斯棘」，也以「飞」状檐。"]},{id:"jie5_s4",label:"图写禽兽，画彩仙灵",showLabel:!0,sentences:[["图写禽兽，画彩仙灵。"]],note:["梁柱墙上画着飞禽走兽，又用彩色绘出神仙灵异，写宫室装饰之盛。","【参看】《楚辞·天问》王逸注谓屈原见楚先王之庙及公卿祠堂「图画天地山川神灵」，可见宫庙壁画之制甚古。"]},{id:"jie5_s5",label:"丙舍旁启，甲帐对楹",showLabel:!0,sentences:[["丙舍旁启，",{text:"甲帐",glossary:"jiazhang"},"对楹。"]],note:["宫中的别室从旁开门，华美的帐幕对着廊柱，写宫室内外的陈设。","【典故】「丙舍」是宫中别室，「甲帐」指华美的帷帐。《汉书·西域传》记汉武帝「设甲乙之帐」，甲乙以次第言其等差。"]},{id:"jie5_s6",label:"肆筵设席，鼓瑟吹笙",showLabel:!0,sentences:[["肆筵设席，鼓瑟吹笙。"]],note:["大摆筵席，鼓瑟吹笙，写宫中的宴乐之盛。","【典故】本《诗·小雅·鹿鸣》：「我有嘉宾，鼓瑟吹笙。」原是宴飨宾客之诗，此处借以写朝会宴享。"]},{id:"jie5_s7",label:"升阶纳陛，弁转疑星",showLabel:!0,sentences:[["升阶纳陛，",{text:"弁",glossary:"bian"},"转疑星。"]],note:["众人登上台阶、入于殿陛；冠上珠饰随步转动，远望疑是繁星。","【典故】「弁」是古代礼冠，《诗·卫风·淇奥》「会弁如星」，即写冠饰玉光闪烁如星。"]},{id:"jie5_s8",label:"右通广内，左达承明",showLabel:!0,sentences:[["右通",{text:"广内",glossary:"guangnei"},"，左达承明。"]],note:["右边通向广内殿，左边通达承明殿——一处藏秘书，一处待贤士。","【典故】广内殿是汉宫收藏秘书之所，承明殿则是文学侍从之臣待诏之处。班固《西都赋》「内有承明、金马，著作之庭」，即指此。"]},{id:"jie5_s9",label:"既集坟典，亦聚群英",showLabel:!0,sentences:[["既集",{text:"坟典",glossary:"fendian"},"，亦聚群英。"]],note:["既收藏了上古典籍，又汇聚了天下英才。这一句是全节的转折：都城的厚重不在宫室，而在典籍与人才。","【典故】「坟典」指三坟、五典，《左传·昭公十二年》有「是能读三坟、五典、八索、九丘」之说，后泛指古书。"]},{id:"jie5_s10",label:"杜稿钟隶，漆书壁经",showLabel:!0,sentences:[[{text:"杜稿钟隶",glossary:"dugao"},"，漆书壁经。"]],note:["杜度的章草、钟繇的隶书，漆写的古书、孔壁中所得的经书——都是最珍贵的字迹与典籍。","【典故】杜度以章草名，钟繇为楷隶之祖；「漆书」是先人以漆书写的古文，「壁经」指汉武帝时自孔子旧宅壁中所得的古文经书（见《汉书·艺文志》）。"]},{id:"jie5_s11",label:"府罗将相，路侠槐卿",showLabel:!0,sentences:[["府罗将相，路侠",{text:"槐卿",glossary:"huaiqing"},"。"]],note:["府中罗列将帅宰相，道路两旁槐树下立着三公九卿。由「文」转入「人」，写朝廷班列。","【典故】周代朝廷植三槐，三公位其下，《周礼·秋官·朝士》「面三槐，三公位焉」，故以「槐卿」称三公九卿。"]},{id:"jie5_s12",label:"户封八县，家给千兵",showLabel:!0,sentences:[["户封八县，家给千兵。"]],note:["封给八县之户，赐给千名兵卒——写功臣受赏之厚。","【参看】汉初功臣封赐之厚，见《史记·萧相国世家》：萧何封酂侯「食邑八千户」，与此句「户封八县」相类。"]},{id:"jie5_s13",label:"高冠陪辇，驱毂振缨",showLabel:!0,sentences:[["高冠陪辇，驱毂振缨。"]],note:["戴着高冠陪同天子车驾，驱车前行，冠缨随风飘动。","【参看】「高冠」是朝会之服，「陪辇」即随驾。汉制有侍中冠等，冠式之别即身分之别。"]},{id:"jie5_s14",label:"世禄侈富，车驾肥轻",showLabel:!0,sentences:[["世禄侈富，车驾肥轻。"]],note:["世代享有俸禄，奢侈富足；车马肥壮，轻裘暖服。","【典故】「肥轻」出《论语·雍也》：「赤之适齐也，乘肥马，衣轻裘。」原记公西赤出使的气派。"]},{id:"jie5_s15",label:"策功茂实，勒碑刻铭",showLabel:!0,sentences:[["策功茂实，勒碑刻铭。"]],note:["记录卓著的功勋，刻石立碑、镌刻铭文，传给后世。全节以「记功」收束。","【典故】勒碑刻铭之制甚古，《礼记·祭统》「铭者，自名也……铭之义，称美而不称恶」，蔡邕《铭论》亦谓碑铭之作以述功德。"]}],j=[{id:"mang",term:"邙",pinyin:"máng",meaning:"北邙山，在洛阳之北。「背邙面洛」写洛阳背山面水的地势。"},{id:"jiazhang",term:"甲帐",pinyin:"jiǎ zhàng",meaning:"华美的帐幕。汉武帝曾「设甲乙之帐」，甲乙以次第分等差。"},{id:"bian",term:"弁",pinyin:"biàn",meaning:"古代男子加冠时所用的一种帽子。《诗·卫风·淇奥》「会弁如星」。"},{id:"guangnei",term:"广内",pinyin:"guǎng nèi",meaning:"汉宫广内殿，为收藏秘书之所；承明殿则是贤士待诏之处。一藏典籍、一聚贤才。"},{id:"fendian",term:"坟典",pinyin:"fén diǎn",meaning:"三坟、五典，传说中上古典籍之名，后泛指古书。见《左传·昭公十二年》。"},{id:"dugao",term:"杜稿钟隶",pinyin:"dù gǎo zhōng lì",meaning:"杜度的章草、钟繇的隶书，都是书法名迹。「漆书」为漆写古书，「壁经」指孔子旧宅壁中所得之经。"},{id:"huaiqing",term:"槐卿",pinyin:"huái qīng",meaning:"周代朝廷植三槐，三公位其下，故以槐卿称三公九卿。见《周礼·秋官·朝士》。"},{id:"erjing",term:"二京",pinyin:"èr jīng",meaning:"西京长安与东京洛阳。汉唐皆两京并置，故称东西二京。"}],c=[{id:"jie6_s1",label:"磻溪伊尹，佐时阿衡",showLabel:!0,sentences:[[{text:"磻溪",glossary:"panxi"},"伊尹，佐时",{text:"阿衡",glossary:"aheng"},"。"]],note:["姜太公钓于磻溪，伊尹出于有莘，都辅佐当时之君，为国之栋梁。全节由「用人」写起。","【典故】姜太公钓于磻溪遇周文王，见《史记·齐太公世家》；伊尹佐商汤，号「阿衡」，见《诗·商颂·长发》「实维阿衡，实左右商王」。"]},{id:"jie6_s2",label:"奄宅曲阜，微旦孰营",showLabel:!0,sentences:[["奄宅曲阜，微旦孰营。"]],note:["奄国故地、曲阜一带，若不是周公旦，谁能经营起来？","【典故】周公东征灭奄，封于曲阜为鲁，见《史记·鲁周公世家》。「微」是「若无」，「旦」即周公姬旦。"]},{id:"jie6_s3",label:"桓公匡合，济弱扶倾",showLabel:!0,sentences:[["桓公匡合，济弱扶倾。"]],note:["齐桓公匡正天下、会合诸侯，救济弱小、扶持倾危。","【典故】《论语·宪问》：「桓公九合诸侯，不以兵车，管仲之力也。」「匡合」即本此。"]},{id:"jie6_s4",label:"绮回汉惠，说感武丁",showLabel:!0,sentences:[["绮回汉惠，",{text:"说感武丁",glossary:"fuyue"},"。"]],note:["绮里季使汉惠帝的太子之位得以保住；傅说感动了商王武丁。","【典故】汉高祖欲废太子，商山四皓出而辅之，其中绮里季最著，见《史记·留侯世家》；武丁梦得贤人，求得傅说为相，殷道复兴，见《尚书·说命》。"]},{id:"jie6_s5",label:"俊乂密勿，多士寔宁",showLabel:!0,sentences:[["俊乂密勿，多士寔宁。"]],note:["贤才勤勉努力，众多贤士使国家安宁。","【典故】本《诗·大雅·文王》：「济济多士，文王以宁。」「俊乂」谓才德过千人者，见《尚书·皋陶谟》「俊乂在官」。"]},{id:"jie6_s6",label:"晋楚更霸，赵魏困横",showLabel:!0,sentences:[["晋楚更霸，赵魏困横。"]],note:["晋、楚交替称霸；赵、魏被「连横」之策所困。","【典故】春秋五霸中晋楚之争最久；战国时秦用张仪「连横」破六国「合纵」，赵魏当其冲。"]},{id:"jie6_s7",label:"假途灭虢，践土会盟",showLabel:!0,sentences:[[{text:"假途灭虢",glossary:"jiaguo"},"，践土会盟。"]],note:["晋献公借虞国的路灭掉虢国，回师时顺手灭虞；晋文公在践土与诸侯会盟。","【典故】「假途灭虢」见《左传·僖公五年》，即「唇亡齿寒」之典；践土之盟见《左传·僖公二十八年》，周襄王亲临，晋文公由此称霸。"]},{id:"jie6_s8",label:"何遵约法，韩弊烦刑",showLabel:!0,sentences:[["何遵约法，韩弊烦刑。"]],note:["萧何遵循「约法三章」的简约之法；韩非之学的弊病在于刑法繁苛。","【典故】刘邦入关，「与父老约，法三章耳」（《史记·高祖本纪》），萧何因之定《九章律》；《史记·韩非列传》谓韩非「喜刑名法术之学」，秦用其说而刑法繁苛。"]},{id:"jie6_s9",label:"起翦颇牧，用军最精",showLabel:!0,sentences:[["起翦颇牧，用军最精。"]],note:["白起、王翦、廉颇、李牧，用兵最为精妙。","【典故】四人即战国四大名将，分属秦、赵，见《史记》各本传。"]},{id:"jie6_s10",label:"宣威沙漠，驰誉丹青",showLabel:!0,sentences:[["宣威沙漠，驰誉丹青。"]],note:["威名远播沙漠之地，美誉流传于史册图画。","【典故】「丹青」指史册图绘，《汉书·苏武传》有「竹帛所载，丹青所画」；汉唐名将宣威漠北，正合此语。"]},{id:"jie6_s11",label:"九州禹迹，百郡秦并",showLabel:!0,sentences:[["九州禹迹，百郡秦并。"]],note:["九州大地留有大禹治水的足迹；百郡之地由秦统一。由「人」转入「地」。","【典故】九州见《尚书·禹贡》；秦并天下，分天下为三十六郡，见《史记·秦始皇本纪》。"]},{id:"jie6_s12",label:"岳宗泰岱，禅主云亭",showLabel:!0,sentences:[["岳宗",{text:"泰岱",glossary:"taidai"},"，禅主云亭。"]],note:["五岳以泰山为宗；封禅之礼以云云、亭亭二山为主。","【典故】《史记·封禅书》记管仲语「古者封泰山禅梁父者七十二家」，其中「禅云云」「禅亭亭」屡见。"]},{id:"jie6_s13",label:"雁门紫塞，鸡田赤城",showLabel:!0,sentences:[["雁门紫塞，鸡田赤城。"]],note:["雁门关、紫塞（长城）、鸡田、赤城，都是著名边塞。","【典故】「紫塞」指长城，因土色紫而名，见崔豹《古今注》「秦筑长城，土色皆紫」。"]},{id:"jie6_s14",label:"昆池碣石，钜野洞庭",showLabel:!0,sentences:[["昆池碣石，钜野洞庭。"]],note:["昆明池、碣石山、钜野泽、洞庭湖——名川大山并举。","【典故】昆明池为汉武帝所凿（《汉书·武帝纪》）；碣石见《尚书·禹贡》「夹右碣石入于河」；钜野为古大泽，见《尚书·禹贡》「大野既猪」；洞庭见《楚辞·九歌》。"]},{id:"jie6_s15",label:"旷远绵邈，岩岫杳冥",showLabel:!0,sentences:[["旷远绵邈，岩岫杳冥。"]],note:["地域旷远绵延，山岩峰峦深远幽冥。","【参看】此二句承上诸地名，以总括语气收住「地理」一层。"]},{id:"jie6_s16",label:"治本于农，务兹稼穑",showLabel:!0,sentences:[["治本于农，务兹",{text:"稼穑",glossary:"jiasi"},"。"]],note:["治国的根本在农业，要致力耕种收获。全节由此转入「农政」。","【典故】《尚书·无逸》记周公戒成王「先知稼穑之艰难」；《管子》「仓廪实则知礼节」，皆以农为本。"]},{id:"jie6_s17",label:"俶载南亩，我艺黍稷",showLabel:!0,sentences:[["俶载南亩，我艺黍稷。"]],note:["开始在南边田里耕作，种下黍与稷。","【典故】本《诗·小雅·大田》「俶载南亩，播厥百谷」，又《诗·小雅·楚茨》「我艺黍稷」。「俶」是开始，「载」是从事。"]},{id:"jie6_s18",label:"税熟贡新，劝赏黜陟",showLabel:!0,sentences:[["税熟贡新，劝赏",{text:"黜陟",glossary:"chuzhi"},"。"]],note:["粮食成熟就缴税、把新粮进贡；劝勉奖赏，贬降或升迁官吏。","【典故】「贡新」即献新谷，《礼记·月令》有「农乃登谷，天子尝新」；「黜陟」见《尚书·舜典》「三载考绩，三考黜陟幽明」。"]}],p=[{id:"panxi",term:"磻溪",pinyin:"pán xī",meaning:"相传姜太公垂钓之处，在今陕西宝鸡一带。此处以「磻溪」代指姜太公。"},{id:"aheng",term:"阿衡",pinyin:"ā héng",meaning:"伊尹的官号、尊称。伊尹辅商汤而兴，是贤相的代称。"},{id:"fuyue",term:"说感武丁",pinyin:"yuè gǎn wǔ dīng",meaning:"殷高宗武丁梦得贤人，求得傅说为相，殷道复兴。「说」指傅说，读 yuè。"},{id:"jiaguo",term:"假途灭虢",pinyin:"jiǎ tú miè guó",meaning:"晋献公向虞国借道伐虢，回师时顺手灭虞。后世喻借路为名、兼并其实。见《左传·僖公五年》。"},{id:"taidai",term:"泰岱",pinyin:"tài dài",meaning:"泰山。五岳以泰山为宗；禅主云亭，指古帝封禅多在云云山、亭亭山。"},{id:"jiasi",term:"稼穑",pinyin:"jià sè",meaning:"种曰稼、收曰穑，合指农事。治本于农、务兹稼穑，是这一节的落脚。"},{id:"chuzhi",term:"黜陟",pinyin:"chù zhì",meaning:"贬降与晋升。税熟贡新之后，以劝赏黜陟考核官吏——农政与吏治相连。《尚书·舜典》。"}],w=[{id:"jie7_s1",label:"孟轲敦素，史鱼秉直",showLabel:!0,sentences:[["孟轲敦素，史鱼秉直。"]],note:["孟子崇尚质朴之道，史鱼秉持正直之节——一位在野的儒者，一位在朝的直臣。","【典故】「孟轲敦素」谓孟子守其素朴之本（《孟子·离娄下》「大人者，言不必信，行不必果，惟义所在」，正是素朴不假）；「史鱼秉直」指卫国大夫史鱼，《论语·卫灵公》记孔子称其「直哉史鱼！邦有道如矢，邦无道如矢」。"]},{id:"jie7_s2",label:"庶几中庸，劳谦谨敕",showLabel:!0,sentences:[["庶几中庸，劳谦谨敕。"]],note:["力求做到中庸，勤劳、谦逊、谨慎、自勉。四个词都是「守分」的功夫。","【典故】「中庸」见《论语·雍也》「中庸之为德也，其至矣乎」；「劳谦」出《易·谦》「劳谦，君子有终，吉」。"]},{id:"jie7_s3",label:"聆音察理，鉴貌辨色",showLabel:!0,sentences:[["聆音察理，鉴貌辨色。"]],note:["听声音以察事理，观容貌以辨神色。两句讲与人相处时的「听得懂、看得明白」。","【参看】《论语·颜渊》「察言而观色」；《孟子·离娄上》「听其言也，观其眸子，人焉廋哉」。"]},{id:"jie7_s4",label:"贻厥嘉猷，勉其祗植",showLabel:!0,sentences:[[{text:"贻厥嘉猷",glossary:"yijue"},"，勉其祗植。"]],note:["把好的谋略留给后人，勉励他们恭敬地培植自己的德行。","【典故】「贻厥」出《诗·大雅·文王有声》「贻厥孙谋，以燕翼子」；「祗植」谓敬慎地树立。"]},{id:"jie7_s5",label:"省躬讥诫，宠增抗极",showLabel:!0,sentences:[["省躬讥诫，宠增抗极。"]],note:["反省自身、接受讥谏告诫；而受到的恩宠越多，越要警惕「高到极处」。","【参看】《易·乾》「亢龙有悔」，正是「宠增抗极」的另一说法。"]},{id:"jie7_s6",label:"殆辱近耻，林皋幸即",showLabel:!0,sentences:[["殆辱近耻，",{text:"林皋",glossary:"lingao"},"幸即。"]],note:["危辱与耻辱临近之时，能退到山林水边，是幸运的。全节的转折就在这一句。","【参看】《老子》「功成名遂身退，天之道」；《易·遁》「遁之时义大矣哉」，都是这一观念的先声。"]},{id:"jie7_s7",label:"两疏见机，解组谁逼",showLabel:!0,sentences:[["两疏见机，",{text:"解组",glossary:"jiezhu"},"谁逼。"]],note:["汉代的疏广、疏受叔侄看清时机而退，解下印绶辞官——没有人逼他们。","【典故】汉宣帝时太子太傅疏广与其侄少傅疏受同日辞官归乡，见《汉书·疏广传》，后世视为功成身退的典范。「解组」即解下印绶，指辞官。"]},{id:"jie7_s8",label:"索居闲处，沉默寂寥",showLabel:!0,sentences:[["索居闲处，沉默寂寥。"]],note:["独居闲处，沉默安静。退下来之后，先写「静」。","【参看】《易·系辞》「君子独立不惧，遁世无闷」，可与此参看。"]},{id:"jie7_s9",label:"求古寻论，散虑逍遥",showLabel:!0,sentences:[["求古寻论，散虑逍遥。"]],note:["探求古书，寻绎论说；散去忧虑，逍遥自在。写退居之后的日课。","【参看】《庄子·刻意》「就薮泽，处闲旷，钓鱼闲处，无为而已矣」，是「散虑逍遥」的注脚。"]},{id:"jie7_s10",label:"欣奏累遣，戚谢欢招",showLabel:!0,sentences:[["欣奏累遣，戚谢欢招。"]],note:["可喜的事来了，积累的烦恼就遣散了；忧愁辞去，欢乐招来。","【参看】《庄子·刻意》「悲乐者，德之邪；喜怒者，道之过」，指向的正是「能遣能招」的心境。"]},{id:"jie7_s11",label:"渠荷的历，园莽抽条",showLabel:!0,sentences:[["渠荷",{text:"的历",glossary:"dili"},"，园莽抽条。"]],note:["池里的荷花明净鲜亮，园中的草木抽出新条。由「人」转入「草木时节」。","【典故】「的历」是鲜明显著的样子，见司马相如《上林赋》「的皪江靡」一类用法。"]},{id:"jie7_s12",label:"枇杷晚翠，梧桐早凋",showLabel:!0,sentences:[["枇杷晚翠，梧桐早凋。"]],note:["枇杷到深秋依然翠绿，梧桐却早早凋落。两句对举，写草木各有其时。","【参看】《庄子·秋水》「物之生也，若骤若驰」，讲的是万物各有其性、各有其时。"]},{id:"jie7_s13",label:"陈根委翳，落叶飘摇",showLabel:!0,sentences:[["陈根",{text:"委翳",glossary:"weiyi"},"，落叶飘摇。"]],note:["陈旧的根株枯倒相掩，落叶在风中飘摇。写草木由盛而衰的一段。","【参看】「委翳」谓枯倒而互相掩蔽，语意近《楚辞·九辩》「草木摇落而变衰」。「落叶飘摇」即自此化出。"]},{id:"jie7_s14",label:"游鹍独运，凌摩绛霄",showLabel:!0,sentences:[["游鹍独运，凌摩",{text:"绛霄",glossary:"jiangxiao"},"。"]],note:["大鹍独自翱翔，凌云直上，擦着红色的高空。承上文草木之衰，忽然一转，写一只大鸟的高飞。","【典故】「鹍」为传说中的大鸟，与《庄子·逍遥游》的鲲鹏相类；「绛霄」指红色的云霄。"]},{id:"jie7_s15",label:"耽读玩市，寓目囊箱",showLabel:!0,sentences:[["耽读玩市，寓目囊箱。"]],note:["沉迷读书，连市集之中也流连；眼目所寄，只在书囊书箱之间。","【典故】此句用东汉王充事：《后汉书·王充传》记其家贫无书，「常游洛阳市肆，阅所卖书，一见辄能诵忆」。"]},{id:"jie7_s16",label:"易輶攸畏，属耳垣墙",showLabel:!0,sentences:[[{text:"易輶",glossary:"yiyou"},"攸畏，属耳垣墙。"]],note:["轻忽轻易之事最可畏惧，因为隔墙有耳。由读书转入「警醒」。","【典故】本《诗·小雅·小弁》：「君子无易由言，耳属于垣。」「易輶」即轻忽，「属耳垣墙」即耳朵贴着墙听。"]},{id:"jie7_s17",label:"具膳餐饭，适口充肠",showLabel:!0,sentences:[["具膳餐饭，适口充肠。"]],note:["备办饭食，只求合口味、填肚子。由这一段起，转入日用起居。","【参看】《礼记·曲礼》有「毋抟饭、毋放饭」等饮食之仪；此句「适口充肠」，则取其简朴。"]},{id:"jie7_s18",label:"饱饫烹宰，饥厌糟糠",showLabel:!0,sentences:[["饱饫烹宰，饥厌",{text:"糟糠",glossary:"zaokang"},"。"]],note:["饱的时候嫌恶烹煮的肉食，饿的时候连酒糟米糠也觉得满足。写人的常情。","【典故】「糟糠」出《后汉书·宋弘传》「贫贱之交不可忘，糟糠之妻不下堂」，本指粗劣食物。"]},{id:"jie7_s19",label:"亲戚故旧，老少异粮",showLabel:!0,sentences:[["亲戚故旧，老少异粮。"]],note:["对亲戚故交，老人和孩子的口粮各有不同。写「待人之别」。","【参看】《孟子·梁惠王上》「老者衣帛食肉，黎民不饥不寒」，正是「老少异粮」的本意。"]},{id:"jie7_s20",label:"妾御绩纺，侍巾帷房",showLabel:!0,sentences:[["妾御绩纺，侍巾帷房。"]],note:["妻妾从事纺织，在卧房里侍奉巾栉。写家内之事。","【参看】《礼记·内则》详载妇人「治丝茧、织纴组紃」之事，此句即本其意。"]},{id:"jie7_s21",label:"纨扇圆絜，银烛炜煌",showLabel:!0,sentences:[["纨扇圆絜，银烛炜煌。"]],note:["细绢做的团扇圆而洁白，银制的蜡烛光明辉煌。这一句收在这一节的家什之上，也引出了下一节的起居。","【典故】「纨扇」是细绢制成的团扇，「炜煌」谓光明灿烂，语本《诗·小雅·斯干》「哕哕其冥，君子攸宁」一类宫室之咏。"]}],x=[{id:"dili",term:"的历",pinyin:"dì lì",meaning:"鲜明、明净的样子。渠荷的历，写池中荷花的鲜亮。"},{id:"weiyi",term:"委翳",pinyin:"wěi yì",meaning:"枯倒而相互掩蔽。陈根委翳、落叶飘摇，写草木由盛而衰的时节。"},{id:"jiangxiao",term:"绛霄",pinyin:"jiàng xiāo",meaning:"红色的云霄。游鹍独运、凌摩绛霄，写大鸟独飞直上。"},{id:"yiyou",term:"易輶",pinyin:"yì yóu",meaning:"易是轻忽、輶是轻。易輶攸畏，指轻忽轻易之事最可畏；下句属耳垣墙，即隔墙有耳。语本《诗·小雅·小弁》。"},{id:"zaokang",term:"糟糠",pinyin:"zāo kāng",meaning:"酒糟与米糠，指粗劣的食物。饱饫烹宰、饥厌糟糠，写饱时与饥时对食物的两种态度。"},{id:"yijue",term:"贻厥嘉猷",pinyin:"yí jué jiā yóu",meaning:"留下好的谋略给后人。语本《诗经·大雅·文王有声》「贻厥孙谋，以燕翼子」；勉其祗植，是勉励后人恭敬培植。"},{id:"lingao",term:"林皋",pinyin:"lín gāo",meaning:"山林水边。殆辱近耻、林皋幸即——临近羞辱耻辱时，幸好还可以退到林泉。"},{id:"jiezhu",term:"解组",pinyin:"jiě zǔ",meaning:"解下印绶，即辞官。两疏见机、解组谁逼：汉疏广、疏受叔侄功成身退，不是被人逼走的。"}],L=[{id:"jie8_s1",label:"昼眠夕寐，蓝笋象床",showLabel:!0,sentences:[["昼眠夕寐，蓝笋象床。"]],note:["白天小憩、夜里安睡；蓝竹编的席子、象牙饰的床榻。由「住」写起。","【参看】「蓝笋」指用蓝竹（一说竹色青蓝）编的席，「象床」是象牙装饰的床。《诗·小雅·斯干》写宫室落成「下莞上簟，乃安斯寝」，正与此句相接。"]},{id:"jie8_s2",label:"弦歌酒宴，接杯举觞",showLabel:!0,sentences:[["弦歌酒宴，接杯举觞。"]],note:["弹琴唱歌、设酒为宴；传杯递盏，开怀畅饮。写宴乐之欢。","【典故】「举觞」出《诗·小雅·宾之初筵》一类的宴饮之诗；弦歌之乐则见《论语·阳货》「弦歌之声」。"]},{id:"jie8_s3",label:"矫手顿足，悦豫且康",showLabel:!0,sentences:[["矫手顿足，悦豫且康。"]],note:["挥动手臂、踏动双足；心中欢悦，身体康健。写宴乐到酣处的样子。","【典故】「不知手之舞之、足之蹈之」，语出《毛诗序》，本是形容诗乐之感人；此处「矫手顿足」正是同一意象。"]},{id:"jie8_s4",label:"嫡后嗣续，祭祀烝尝",showLabel:!0,sentences:[["嫡后嗣续，祭祀",{text:"烝尝",glossary:"zhengchang"},"。"]],note:["嫡子继承先祖的后嗣，四时按礼祭祀。血脉与礼，两重延续。","【典故】「烝尝」是祭祀之名：冬祭曰烝、秋祭曰尝，见《诗·小雅·天保》「禴祠烝尝，于公先王」。"]},{id:"jie8_s5",label:"稽颡再拜，悚惧恐惶",showLabel:!0,sentences:[[{text:"稽颡",glossary:"qisang"},"再拜，悚惧恐惶。"]],note:["叩头再拜，心中敬畏惶恐。写祭祖时的态度。","【典故】「稽颡」是以额触地的大礼，见《礼记·檀弓》；「悚惧恐惶」写祭时「祭如在」的那种敬畏，《论语·八佾》「祭如在，祭神如神在」可与之参看。"]},{id:"jie8_s6",label:"笺牒简要，顾答审详",showLabel:!0,sentences:[[{text:"笺牒",glossary:"jiandie"},"简要，顾答审详。"]],note:["写信写文要简明扼要，回答别人的问话要审慎详尽。一简一详，各有分寸。","【参看】「笺牒」指书信文牒；「顾答」即回话。此句讲的是文书与应对的两条准则。"]},{id:"jie8_s7",label:"骸垢想浴，执热愿凉",showLabel:!0,sentences:[["骸垢想浴，执热愿凉。"]],note:["身上脏了就想沐浴，手里拿着热的东西就希望凉快。写的是人之常情。","【参看】《礼记·大学》「如恶恶臭，如好好色」，讲的是不加勉强的自然之情；此句亦然。"]},{id:"jie8_s8",label:"驴骡犊特，骇跃超骧",showLabel:!0,sentences:[["驴骡犊特，骇跃",{text:"超骧",glossary:"chaoxiang"},"。"]],note:["驴、骡、小牛、公牛，受惊后腾跃奔驰、昂首飞跑。写牲畜之动，与上文人情相对。","【典参】「特」指公牛（《诗·小雅·无羊》「三十维物，尔牲则具」）；「骧」是马昂首奔腾的样子。"]},{id:"jie8_s9",label:"诛斩贼盗，捕获叛亡",showLabel:!0,sentences:[["诛斩贼盗，捕获叛亡。"]],note:["诛杀贼人盗匪，捕获叛逆逃亡的人。由家事说到国法。","【参看】《尚书·舜典》有「寇贼奸宄」之目；此句讲的是除害安民，与下文的「技艺」形成一正一奇。"]},{id:"jie8_s10",label:"布射僚丸，嵇琴阮啸",showLabel:!0,sentences:[["布射僚丸，嵇琴阮啸。"]],note:["吕布善射，宜僚弄丸；嵇康善琴，阮籍善啸。四位各有绝技的人。","【典故】吕布辕门射戟，见《三国志·吕布传》；宜僚弄丸而解两家之难，见《庄子·徐无鬼》；嵇康善弹琴，临刑奏《广陵散》（《世说新语·雅量》）；阮籍善啸，见《世说新语·栖逸》。"]},{id:"jie8_s11",label:"恬笔伦纸，钧巧任钓",showLabel:!0,sentences:[["恬笔伦纸，钧巧任钓。"]],note:["蒙恬制笔，蔡伦造纸；马钧有巧思，任公子善钓鱼。笔墨器物与能工巧匠并举。","【典故】蒙恬造笔之说见《太平御览》引《博物志》；蔡伦造纸见《后汉书·蔡伦传》；马钧以巧思著称，见《三国志·杜夔传》裴注；任公子为大钩巨缁钓于东海，见《庄子·外物》。"]},{id:"jie8_s12",label:"释纷利俗，并皆佳妙",showLabel:!0,sentences:[["释纷利俗，并皆佳妙。"]],note:["这些技艺能解开纠纷、便利世俗，都很精妙。一句总收上文的各类技艺。","【参看】《易·系辞》「备物致用，立成器以为天下利」，正可作此句的注脚。"]},{id:"jie8_s13",label:"毛施淑姿，工颦妍笑",showLabel:!0,sentences:[["毛施淑姿，工颦妍笑。"]],note:["毛嫱、西施姿容美好，皱眉与含笑都很美。由技艺转到人。","【典故】毛嫱、西施是古代著名的美人，见《庄子·齐物论》「毛嫱、西施，人之所美也」；「工颦」本指西施心痛而颦，见《庄子·天运》。"]},{id:"jie8_s14",label:"年矢每催，曦晖朗曜",showLabel:!0,sentences:[["年矢每催，曦晖朗曜。"]],note:["光阴像箭一样不断催人，太阳的光辉明亮照耀。由「人」转入「天时」。","【典故】「年矢」谓岁月如矢，语意本《庄子·知北游》「人生天地之间，若白驹之过郤」；「曦晖」指日光的照耀。"]},{id:"jie8_s15",label:"璇玑悬斡，晦魄环照",showLabel:!0,sentences:[[{text:"璇玑",glossary:"xuanji"},"悬斡，晦魄环照。"]],note:["北斗的璇玑悬着旋转，月魄的明晦循环相照。写星辰日月的不停运转。","【典故】「璇玑」是北斗七星中的部分，也指古代测天的浑天仪一类，见《尚书·舜典》「在璇玑玉衡，以齐七政」；「晦魄」指月之明晦。"]},{id:"jie8_s16",label:"指薪修祜，永绥吉劭",showLabel:!0,sentences:[[{text:"指薪修祜",glossary:"zhixin"},"，永绥吉劭。"]],note:["薪有尽而火传不尽，因此要修身积福；愿长久安宁、吉祥美好。这是全篇的祝愿处。","【典故】本《庄子·养生主》：「指穷于为薪，火传也，不知其尽也。」「修祜」是修福，「永绥吉劭」是长久安好。"]},{id:"jie8_s17",label:"矩步引领，俯仰廊庙",showLabel:!0,sentences:[["矩步引领，俯仰廊庙。"]],note:["步伐合于规矩，引领而望；在朝廷上俯仰进退。写身在朝堂的仪态。","【参看】《礼记·曲礼》详载「行不中道，立不中门」之类步趋之仪，「矩步」即本此。"]},{id:"jie8_s18",label:"束带矜庄，徘徊瞻眺",showLabel:!0,sentences:[[{text:"束带矜庄",glossary:"shudai"},"，徘徊瞻眺。"]],note:["整束衣带、端庄自持；徘徊顾盼，瞻望远方。与上句连写四种在朝廷的仪态。","【典故】「束带」谓整饬衣冠，《论语·公冶长》有「束带立于朝」；「矜庄」即庄敬自持。"]},{id:"jie8_s19",label:"孤陋寡闻，愚蒙等诮",showLabel:!0,sentences:[["孤陋寡闻，愚蒙等诮。"]],note:["见识孤陋、见闻寡少，愚昧无知，一同受人讥笑。这是作者的自谦之辞。","【参看】《礼记·学记》「独学而无友，则孤陋而寡闻」，正是「孤陋寡闻」的出处。"]},{id:"jie8_s20",label:"谓语助者，焉哉乎也",showLabel:!0,sentences:[["谓语助者，焉哉乎也。"]],note:["至于语助词，就是「焉」「哉」「乎」「也」这几个。以四个虚字作结，全篇至此正好一千字。","【参看】古人以「之乎者也」为语助之常，《文心雕龙·章句》有「之而于以者，乃劄句之旧体」之说；《千字文》以虚字收尾，正是「以实起、以虚收」的手法。"]}],_=[{id:"zhengchang",term:"烝尝",pinyin:"zhēng cháng",meaning:"冬祭曰烝、秋祭曰尝，合指四时祭祀。嫡后嗣续、祭祀烝尝，写的是血脉与礼的两重延续。"},{id:"qisang",term:"稽颡",pinyin:"qǐ sǎng",meaning:"叩头，以额触地。稽颡再拜、悚惧恐惶，写祭祖时的恭敬与敬畏。"},{id:"jiandie",term:"笺牒",pinyin:"jiān dié",meaning:"书信与文牒。笺牒简要、顾答审详——写出去的从简，答回来的要详。"},{id:"chaoxiang",term:"超骧",pinyin:"chāo xiāng",meaning:"骧是马昂首奔腾。骇跃超骧，写驴骡犊特受惊后腾跃奔驰之状。"},{id:"xuanji",term:"璇玑",pinyin:"xuán jī",meaning:"北斗七星中可转动的部分，也指浑天仪一类测天之物。璇玑悬斡、晦魄环照，写星辰运转、月魄明晦循环。"},{id:"zhixin",term:"指薪修祜",pinyin:"zhǐ xīn xiū hù",meaning:"语本《庄子·养生主》「指穷于为薪，火传也，不知其尽也」——柴有尽而火相传。修祜是修福，永绥吉劭是愿长久安宁吉祥。"},{id:"shudai",term:"束带矜庄",pinyin:"shù dài jīn zhuāng",meaning:"整束衣带、端庄自持。矩步引领、俯仰廊庙、束带矜庄、徘徊瞻眺，连写四种在朝廷进退顾盼的仪态。"}];return(D,n)=>{const z=l("DaoReadingPrelude"),s=l("DaoTextReading"),a=l("DaoKeywordCards");return q(),k("div",null,[n[0]||(n[0]=e("h1",{id:"千字文-·-全篇",tabindex:"-1"},[i("千字文 · 全篇 "),e("a",{class:"header-anchor",href:"#千字文-·-全篇","aria-label":'Permalink to "千字文 · 全篇"'},"​")],-1)),t(z,{title:"一千字里的中国：先通读，再八节细看",summary:"《千字文》四字一句、两句一韵，一千字不重不漏，本是为识字而编，却由识字铺开成一篇缩写的中国文化小百科：从天地开辟讲到日用起居，中间插入上古史、修身、人伦、都邑、史地与农政。这一页把全文按内容分为八节，每节都有原文、一句引读与该节字词。",points:[{label:"先读",text:"先顺着八节把原文通读一遍，遇到不认得的字不必停下。"},{label:"再辨",text:"留意它的走法：由天及地、由外及内、由史及身，一层层收到日用。"},{label:"后想",text:"读完之后再看：这一千字里，哪几句和你现在的日子有关。"}],hint:"竹简 / 经典两种读法可随时切换（切换后全页同步）；经典模式下点带底色的词可看释义，每句释义点句首标签展开，右上角「打开释义」可一键全开。"}),n[1]||(n[1]=e("h2",{id:"jie-1",tabindex:"-1"},[i("一、天地自然 "),e("a",{class:"header-anchor",href:"#jie-1","aria-label":'Permalink to "一、天地自然 {#jie-1}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第一节原文：天地自然",sections:o,glossary:r}),n[2]||(n[2]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：前五句讲天——颜色、日月、寒暑、闰律、云霜；后四句落地——金玉剑珠、果蔬、海河鱼鸟。先看清这层天／地之分，再看它其实是按「由远及近、由大到小」排下来的。（"),e("strong",null,"每段释义点段首标签展开"),i("；右上角「打开释义」可一键全开。）")])],-1)),t(a,{items:[{term:"玄黄",pinyin:["xuán","huáng"],meaning:"天玄而地黄。语本《易·坤·文言》「夫玄黄者，天地之杂也，天玄而地黄」，指天地初成时的颜色。"},{term:"洪荒",pinyin:["hóng","huāng"],meaning:"广大荒远、浑沌未分的样子。宇指上下四方，宙指古往今来，「宇宙」合起来就是时间与空间。"},{term:"盈昃",pinyin:["yíng","zè"],meaning:"月圆为盈、日斜为昃。《易·丰》「日中则昃，月盈则食」讲的是同一个道理：到极处就要转。"},{term:"闰余成岁",pinyin:["rùn","yú","chéng","suì"],meaning:"置闰以成年。阴历一年约三百五十四日，与太阳年差约十一日，三年一闰、五年再闰，才不至于寒暑错位。"},{term:"律吕调阳",pinyin:["lǜ","lǚ","tiáo","yáng"],meaning:"以十二律对应十二月来调正节气。律为阳声、吕为阴声，古人候气于律管，观其应时而动。"},{term:"丽水",pinyin:["lì","shuǐ"],meaning:"古称金沙江为丽水，一说其地出金。「金生丽水」即金沙出于丽水。"},{term:"昆冈",pinyin:["kūn","gāng"],meaning:"昆仑山，古以为产玉之地。《尚书·胤征》有「火炎昆冈，玉石俱焚」之语。"},{term:"李柰芥姜",pinyin:["lǐ","nài","jiè","jiāng"],meaning:"李、柰是果中珍品，芥、姜是菜中要味。「菜重芥姜」的「重」是看重，不是分量重。"},{term:"鳞潜羽翔",pinyin:["lín","qián","yǔ","xiáng"],meaning:"鱼在水中潜、鸟在空中翔——由海河写到水陆众生，收束这一节的自然之景。"}]}),n[3]||(n[3]=e("h2",{id:"jie-2",tabindex:"-1"},[i("二、上古治世 "),e("a",{class:"header-anchor",href:"#jie-2","aria-label":'Permalink to "二、上古治世 {#jie-2}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第二节原文：上古治世",sections:g,glossary:d}),n[4]||(n[4]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：这一节是压缩过的上古史：先立官制与文字衣裳，再讲禅让与征伐，末尾落在「德化所及」。留意「吊民伐罪」与「垂拱平章」并置——除暴与无为，是古人心中治世的两只手。")])],-1)),t(a,{items:[{term:"龙师火帝",pinyin:["lóng","shī","huǒ","dì"],meaning:"伏羲氏以龙纪官，神农氏以火纪官。指上古以图腾、以火政命名官制的传说时代。"},{term:"鸟官人皇",pinyin:["niǎo","guān","rén","huáng"],meaning:"少昊氏以鸟名官，人皇氏为传说中三皇之一。连上句，泛指三皇五帝之世。"},{term:"始制文字",pinyin:["shǐ","zhì","wén","zì"],meaning:"传说黄帝之史仓颉造字。有了文字，政令与经验才可传之久远。"},{term:"乃服衣裳",pinyin:["nǎi","fú","yī","shang"],meaning:"传说黄帝制衣裳、嫘祖养蚕。自此有了服制，人别于禽兽。"},{term:"推位让国",pinyin:["tuī","wèi","ràng","guó"],meaning:"禅让：尧让位于舜、舜让位于禹，不传子而传贤。"},{term:"有虞陶唐",pinyin:["yǒu","yú","táo","táng"],meaning:"有虞氏指舜，陶唐氏指尧。以氏号代称两位古帝。"},{term:"吊民伐罪",pinyin:["diào","mín","fá","zuì"],meaning:"抚慰百姓、讨伐暴君。周发指周武王姬发，殷汤指商汤，指汤伐桀、武伐纣。"},{term:"垂拱平章",pinyin:["chuí","gǒng","píng","zhāng"],meaning:"垂衣拱手而天下治，同时辨明政事得失。无为不是不问事，是先把人和制度立好。"},{term:"鸣凤在竹",pinyin:["míng","fèng","zài","zhú"],meaning:"凤凰鸣于竹间、白马食于场圃，古人以为德政所致之祥瑞。二句是「化被草木」的图景。"}]}),n[5]||(n[5]=e("h2",{id:"jie-3",tabindex:"-1"},[i("三、修身之本 "),e("a",{class:"header-anchor",href:"#jie-3","aria-label":'Permalink to "三、修身之本 {#jie-3}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第三节原文：修身之本",sections:m,glossary:h}),n[6]||(n[6]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：从「身体发肤」起，经改过、言行、德行，收到惜时。三组对举值得停一停：知过必改／得能莫忘，罔谈彼短／靡恃己长，信使可覆／器欲难量——讲的都是「向内收」。")])],-1)),t(a,{items:[{term:"盖此身发",pinyin:["gài","cǐ","shēn","fà"],meaning:"语本《孝经》「身体发肤，受之父母，不敢毁伤，孝之始也」。盖是发语词，这一节由此起。"},{term:"四大五常",pinyin:["sì","dà","wǔ","cháng"],meaning:"四大为地水火风，五常为仁义礼智信。一句里把「身」与「德」两样根基一起立住。"},{term:"恭惟鞠养",pinyin:["gōng","wéi","jū","yǎng"],meaning:"恭敬地想父母抚育之劳；由此才有「岂敢毁伤」——不敢轻慢这具受之父母的身体。"},{term:"墨悲丝染",pinyin:["mò","bēi","sī","rǎn"],meaning:"《墨子·所染》载墨子见染丝而悲：丝入青则青、入黄则黄，一染便难复白。喻人所处所习，熏染最要紧。"},{term:"诗赞羔羊",pinyin:["shī","zàn","gāo","yáng"],meaning:"《诗经·召南·羔羊》以「羔羊之皮，素丝五紽」称美在位者节俭正直。"},{term:"景行维贤",pinyin:["jǐng","xíng","wéi","xián"],meaning:"效法大道上的贤者。「维」是维系、依循。"},{term:"克念作圣",pinyin:["kè","niàn","zuò","shèng"],meaning:"能克制杂念、念念守正，就可以作圣人。语本《尚书·多方》「惟圣罔念作狂，惟狂克念作圣」。"},{term:"空谷传声",pinyin:["kōng","gǔ","chuán","shēng"],meaning:"空谷里喊一声，回响清楚；虚堂之中，声音易听。喻心空则能受、能察。"},{term:"尺璧寸阴",pinyin:["chǐ","bì","cùn","yīn"],meaning:"语本《淮南子》「圣人不贵尺之璧而重寸之阴」。一尺美玉不算宝，一寸光阴才值得去争。"}]}),n[7]||(n[7]=e("h2",{id:"jie-4",tabindex:"-1"},[i("四、人伦持守 "),e("a",{class:"header-anchor",href:"#jie-4","aria-label":'Permalink to "四、人伦持守 {#jie-4}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第四节原文：人伦持守",sections:u,glossary:b}),n[8]||(n[8]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：这是全书最长的一节，可分五层顺读：做人的本分（孝忠、谨敬）→ 做事的仪态（容止、慎终）→ 出仕的次第（学优登仕、甘棠遗爱）→ 家中人伦（傅训母仪、姑叔兄弟、交友）→ 心性（性静情逸、守真志满）。末尾「好爵自縻」是落点：里面守得住，外面的名位反而自来。")])],-1)),t(a,{items:[{term:"资父事君",pinyin:["zī","fù","shì","jūn"],meaning:"以事父之道事君。语本《孝经》「资于事父以事君，而敬同」。严与敬，是这一节的总纲。"},{term:"临深履薄",pinyin:["lín","shēn","lǚ","bó"],meaning:"如临深渊、如履薄冰。语出《诗经·小雅·小旻》，形容存心戒慎。"},{term:"夙兴温凊",pinyin:["sù","xīng","wēn","qìng"],meaning:"早起操持，冬使父母温、夏使父母凉。是「孝当竭力」落到日常的样子。"},{term:"川流不息",pinyin:["chuān","liú","bù","xī"],meaning:"如河水奔流不止，如深潭澄澈可照——一喻德泽绵长，一喻心境清明。"},{term:"笃初慎终",pinyin:["dǔ","chū","shèn","zhōng"],meaning:"开头诚恳固然好，能慎重收尾更难。《诗经》「靡不有初，鲜克有终」说的是同一件事。"},{term:"学优登仕",pinyin:["xué","yōu","dēng","shì"],meaning:"学有余力便出仕任事。语本《论语》「学而优则仕」；摄职从政，是代理职事、参与政务。"},{term:"甘棠遗爱",pinyin:["gān","táng","yí","ài"],meaning:"召伯听政于甘棠树下，去后民思其人而爱其树。后世以「甘棠遗爱」称颂离任后仍被怀念的惠政。"},{term:"孔怀同气",pinyin:["kǒng","huái","tóng","qì"],meaning:"兄弟最为相念，同气连枝如一棵树上的枝干，血脉同源。"},{term:"好爵自縻",pinyin:["hǎo","jué","zì","mí"],meaning:"美好的爵位会自己系到身上。「縻」是系、拴。内守雅操，外来的名位反而不必去求。"}]}),n[9]||(n[9]=e("h2",{id:"jie-5",tabindex:"-1"},[i("五、都邑典籍 "),e("a",{class:"header-anchor",href:"#jie-5","aria-label":'Permalink to "五、都邑典籍 {#jie-5}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第五节原文：都邑典籍",sections:y,glossary:j}),n[10]||(n[10]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：先立两京形势，再写宫殿朝会，然后一转——「既集坟典，亦聚群英」：都城的厚重不在宫室，而在典籍与人才。读时留意它「由景入人、由人入文」的次序，末尾又回到功臣世禄与刻石记功。")])],-1)),t(a,{items:[{term:"东西二京",pinyin:["dōng","xī","èr","jīng"],meaning:"洛阳为东京、长安为西京。华夏是中国的旧称——这一句把「都城」放到天下的尺度上说。"},{term:"背邙面洛",pinyin:["bèi","máng","miàn","luò"],meaning:"洛阳背靠北邙山、面朝洛水；长安则渭水环绕、泾水为据。两句写形胜，也写择都之理。"},{term:"宫殿盘郁",pinyin:["gōng","diàn","pán","yù"],meaning:"宫殿曲折深远、层层叠叠，楼观高峻欲飞，望之令人惊。"},{term:"丙舍甲帐",pinyin:["bǐng","shè","jiǎ","zhàng"],meaning:"别室在旁开启，华帐对着厅柱。写宫室的陈设排布。"},{term:"弁转疑星",pinyin:["biàn","zhuǎn","yí","xīng"],meaning:"登阶入殿时冠饰转动，望去像一片星。写朝会仪容之盛。"},{term:"广内承明",pinyin:["guǎng","nèi","chéng","míng"],meaning:"广内殿藏书，承明殿待士。右通、左达两语，把宫室与文事连在一起。"},{term:"杜稿钟隶",pinyin:["dù","gǎo","zhōng","lì"],meaning:"杜度的章草、钟繇的隶书，与漆书、壁经并举——写典籍与书法之富。"},{term:"路侠槐卿",pinyin:["lù","xiá","huái","qīng"],meaning:"府中罗列将相，路上夹道而立的是三公九卿。「侠」通「夹」。"},{term:"勒碑刻铭",pinyin:["lè","bēi","kè","míng"],meaning:"把功劳刻在碑石与铭器上。策功茂实、勒碑刻铭，是这一节写功业的落点。"}]}),n[11]||(n[11]=e("h2",{id:"jie-6",tabindex:"-1"},[i("六、史地农政 "),e("a",{class:"header-anchor",href:"#jie-6","aria-label":'Permalink to "六、史地农政 {#jie-6}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第六节原文：史地农政",sections:c,glossary:p}),n[12]||(n[12]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：前半是人事，后半是地理与农政，两个字一个典故。不必纠缠每个名字，先看清两层：一讲用人得失（贤相、霸主、名将、律法），一讲守土养民（九州、五岳、边塞、稼穑）。末尾「劝赏黜陟」把土地与治人接到一起。")])],-1)),t(a,{items:[{term:"磻溪伊尹",pinyin:["pán","xī","yī","yǐn"],meaning:"姜太公钓于磻溪而佐周，伊尹耕于有莘之野而佐商。两个「待时而动」的贤相。"},{term:"奄宅曲阜",pinyin:["yǎn","zhái","qū","fù"],meaning:"周公旦受封于曲阜（鲁国）；微旦孰营——若没有周公，谁来经营周室的基业。"},{term:"桓公匡合",pinyin:["huán","gōng","kuāng","hé"],meaning:"齐桓公九合诸侯、匡正天下，济弱扶倾：扶助弱小、援救倾危。"},{term:"绮回汉惠",pinyin:["qǐ","huí","hàn","huì"],meaning:"商山四皓中的绮里季出山，使刘邦打消废太子之念，保住了后来的汉惠帝。"},{term:"俊乂密勿",pinyin:["jùn","yì","mì","wù"],meaning:"俊乂指才德出众之士，密勿是勤勉用事。多士寔宁：人才众而国乃安。"},{term:"约法烦刑",pinyin:["yuē","fǎ","fán","xíng"],meaning:"萧何依刘邦「约法三章」而定汉律，律简而得人心；韩非之说主张严刑繁法，反受其弊。一句对照，讲的是法与治的分寸。"},{term:"起翦颇牧",pinyin:["qǐ","jiǎn","pō","mù"],meaning:"白起、王翦、廉颇、李牧——战国四位最善用兵的名将。"},{term:"驰誉丹青",pinyin:["chí","yù","dān","qīng"],meaning:"名声流传于图画之中。汉宣帝曾画功臣像于麒麟阁，后世以「丹青」代指功名图画。"},{term:"九州禹迹",pinyin:["jiǔ","zhōu","yǔ","jì"],meaning:"九州是禹治水后所划的天下区划，百郡是秦统一后所置之郡——疆域的两次定型。"}]}),n[13]||(n[13]=e("h2",{id:"jie-7",tabindex:"-1"},[i("七、为政隐逸 "),e("a",{class:"header-anchor",href:"#jie-7","aria-label":'Permalink to "七、为政隐逸 {#jie-7}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第七节原文：为政隐逸",sections:w,glossary:x}),n[14]||(n[14]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：这一节从「为政」转向「退居」：前六句讲在朝的操守与戒备（宠增抗极），第七句「林皋幸即」一转，后面便是退下来的日子——独处、读书、看草木荣枯。「两疏见机，解组谁逼」是这一转的关键：主动退，而不是被逼退。")])],-1)),t(a,{items:[{term:"孟轲敦素",pinyin:["mèng","kē","dūn","sù"],meaning:"孟轲即孟子，敦素是笃厚朴素；史鱼是卫国大夫，以刚直著称。一动一静，是两种「直」。"},{term:"庶几中庸",pinyin:["shù","jī","zhōng","yōng"],meaning:"力求合乎中庸，勤劳谦逊、谨慎自戒。「劳谦」出《易·谦》「劳谦君子，有终吉」。"},{term:"聆音察理",pinyin:["líng","yīn","chá","lǐ"],meaning:"听声音以辨情理，看容貌以别神色——审事察人的细功夫。"},{term:"省躬讥诫",pinyin:["xǐng","gōng","jī","jiè"],meaning:"反省自身、接纳讥诫。宠增抗极：恩宠越盛，越要防备「至极则反」。"},{term:"两疏见机",pinyin:["liǎng","shū","jiàn","jī"],meaning:"汉宣帝时疏广、疏受叔侄并为太子师傅，位高而主动请退，归乡以寿终。见机，是看见那个「该退」的时机。"},{term:"散虑逍遥",pinyin:["sàn","lǜ","xiāo","yáo"],meaning:"排遣忧虑而得自在。求古寻论、散虑逍遥，写退居后的日常：读书、论古、散心。"},{term:"耽读玩市",pinyin:["dān","dú","wán","shì"],meaning:"耽溺读书、玩味于市。后汉王充家贫无书，常游洛阳书肆，读所卖之书一见即能诵——用其事。"},{term:"属耳垣墙",pinyin:["zhǔ","ěr","yuán","qiáng"],meaning:"隔墙有耳。语本《诗经·小雅》「君子无易由言，耳属于垣」——说话轻易，最该提防。"},{term:"纨扇银烛",pinyin:["wán","shàn","yín","zhú"],meaning:"绢制团扇圆而洁净，银烛光辉明亮（炜煌）。写居处器物之清雅，与上一节的宫室之盛恰成对照。"}]}),n[15]||(n[15]=e("h2",{id:"jie-8",tabindex:"-1"},[i("八、起居收束 "),e("a",{class:"header-anchor",href:"#jie-8","aria-label":'Permalink to "八、起居收束 {#jie-8}"'},"​")],-1)),t(s,{tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"《千字文》第八节原文：起居收束",sections:L,glossary:_}),n[16]||(n[16]=e("blockquote",null,[e("p",null,[e("strong",null,"引读"),i("：收尾一节：先写日用起居与祭祀，再列技艺（射、丸、琴、啸、笔、纸、巧、钓），继以美人与天时（年矢、璇玑、晦魄）过渡，最后落到「指薪修祜」的祝愿，并以四个语助词收束——「焉哉乎也」。全文到此，正好一千字。")])],-1)),t(a,{items:[{term:"蓝笋象床",pinyin:["lán","sǔn","xiàng","chuáng"],meaning:"蓝笋是竹席，象床是象牙装饰之床。昼眠夕寐、蓝笋象床，写居处安适——这是全书由大及小收拢的第一步。"},{term:"弦歌酒宴",pinyin:["xián","gē","jiǔ","yàn"],meaning:"弦歌设宴、接杯举觞；矫手顿足，悦豫且康——写宴饮之乐，手足起舞而身心安和。"},{term:"稽颡再拜",pinyin:["qǐ","sǎng","zài","bài"],meaning:"叩头再拜、心怀敬畏。这一句与前面的「弦歌酒宴」相接，是古人生活里乐与敬的两面。"},{term:"骸垢想浴",pinyin:["hái","gòu","xiǎng","yù"],meaning:"身上有垢便想沐浴，手里执热便愿清凉——写人情之常。古人以这类「人之常情」收束日用之事。"},{term:"布射僚丸",pinyin:["bù","shè","liáo","wán"],meaning:"吕布射戟以解刘备之围，宜僚弄丸而使楚宋之兵不战——一武一技，都能排解纷争。"},{term:"嵇琴阮啸",pinyin:["jī","qín","ruǎn","xiào"],meaning:"嵇康善琴、阮籍长啸，是魏晋名士的两种自处方式。"},{term:"恬笔伦纸",pinyin:["tián","bǐ","lún","zhǐ"],meaning:"相传蒙恬改良毛笔、蔡伦改进造纸。钧巧任钓：马钧之巧、任公子之钓。四句连写技艺与器物。"},{term:"毛施淑姿",pinyin:["máo","shī","shū","zī"],meaning:"毛嫱（一说毛嫱为越地美姬）与西施，姿容美好；工颦妍笑，指善颦与美笑皆成妍态。"},{term:"谓语助者",pinyin:["wèi","yǔ","zhù","zhě"],meaning:"末句以「焉、哉、乎、也」四个语助词收尾。全文一千字不重不漏，最后落在四个虚字上，反倒最见巧思。"}]}),n[17]||(n[17]=P("",14))])}}});export{v as __pageData,C as default};
